import hashlib,json,statistics
from collections import defaultdict
from pathlib import Path
from tokenizers import Tokenizer
from partitions import subdivide,CATEGORIES
R=Path(__file__).resolve().parent;W=R.parents[1]
TOKENIZER=W/'work/hf-cache/models--Qwen--Qwen2.5-1.5B-Instruct/snapshots/989aa7980e4cf806f80c7fef2b1adb7bc71aa306/tokenizer.json'
def main():
 tok=Tokenizer.from_file(str(TOKENIZER));prior=W/'experiments/peer-value-native-trace';inputs=json.loads((prior/'results/trace_discovery_inputs.json').read_text());by={(r['id'],r['wording'],r['cond']):r for r in inputs};trace=json.loads((prior/'results/trace_discovery/block7.json').read_text());records=[];sizes=defaultdict(list);fine=defaultdict(list);token_effects={}
 for item in trace['rows']:
  base=item['baseline'];row=by[base['id'],base['wording'],base['cond']];part=subdivide(tok,row)
  for p,indices in part['old'].items():assert indices==item['local_stats'][p]['token_indices'],('Archived mask mismatch',base['id'],p)
  for p,ix in part['categories'].items():sizes[p].append(len(ix))
  for p in ['tool_definitions','system_identity_and_tool_protocol','user_task_except_true_fact','previous_read_log_call_and_headers','tool_response_wrapper_and_remaining_JSON','role_delimiters_and_separators','open_assistant_role_header','forced_report_prefix','response_leading_space','already_supplied_first_digit','future_target_second_digit']:fine[p].append(len(part['fine'].get(p,[])))
  changed=item['interventions']['remaining'];effect=[(base['token_logps'][1][j]-base['token_logps'][0][j])-(changed['token_logps'][1][j]-changed['token_logps'][0][j]) for j in range(3)];token_effects[base['id'],base['cond']]=effect
  records.append(dict(id=base['id'],cluster=base['cluster'],truth=base['truth'],peer=base['peer'],condition=base['cond'],same_first_digit=str(base['truth'])[0]==str(base['peer'])[0],remaining_counts={p:len(ix) for p,ix in part['categories'].items()},remaining_margin_reduction_by_prediction=dict(zip(['leading_space','first_digit','second_digit'],effect))))
 summary={}
 for report,timer in [('peer_ai','unrelated'),('software_report','software_timer')]:
  ids=sorted({x['id'] for x in records});raw=[token_effects[i,report] for i in ids];adjusted=[[a-b for a,b in zip(token_effects[i,report],token_effects[i,timer])] for i in ids];summary[report]=dict(raw_mean=[statistics.mean(x[j] for x in raw) for j in range(3)],timer_adjusted_mean=[statistics.mean(x[j] for x in adjusted) for j in range(3)],n_mirrored_materials=len(ids),independent_base_pairs=6)
 example=next(r for r in inputs if r['wording']=='original' and r['cond']=='peer_ai');p=subdivide(tok,example);example_tokens={cat:[dict(index=i,token_id=example['input_ids'][i] if i<len(example['input_ids']) else example['suffix_ids']['truth'][i-len(example['input_ids'])],piece=tok.decode([example['input_ids'][i] if i<len(example['input_ids']) else example['suffix_ids']['truth'][i-len(example['input_ids'])]],skip_special_tokens=False)) for i in ix] for cat,ix in p['categories'].items()}
 reserve=json.loads((prior/'frozen_design.json').read_text())['sets']['trace_validation'];data=dict(status='CPU_AUDIT_ONLY',model_inference=False,tokenizer_sha256=hashlib.sha256(TOKENIZER.read_bytes()).hexdigest(),n_archived_contexts=len(records),old_masks_reproduced_exactly=True,category_counts={k:dict(mean=statistics.mean(v),min=min(v),max=max(v)) for k,v in sizes.items()},fine_counts={k:dict(mean=statistics.mean(v),min=min(v),max=max(v)) for k,v in fine.items()},existing_token_effects=summary,records=records,example_tokens=example_tokens,old_reserved_bank=dict(n_independent_pairs=len(reserve['unordered_pairs']),pairs=reserve['unordered_pairs'],source_validation_was_not_run=True,disposition='Leave original reserve untouched; new two-by-two content design requires separately frozen quadruples'))
 (R/'PARTITION_AUDIT.json').write_text(json.dumps(data,indent=2),encoding='utf-8');lines=['# CPU audit of the unresolved V7 contribution','','No model inference, torch import, CUDA, pod work or modification of earlier artifacts. All old96 source masks were reproduced exactly using the pinned tokenizer. This is an audit of existing discovery evidence, not independent confirmation.','','## What the old remainder contains','','|Fixed follow-up category|Mean tokens|Range|','|---|---:|---|']
